mapper.select:
SELECT bdi.billDetailId, bdi.itemId, bdi.itemNum, bdi.itemName, bdi.itemType, bdi.categoryId, bdi.categoryName, bdi.billNum, DATE_FORMAT( bdi.orderDate, '%Y-%m-%d' ) as orderDate, bdi.patientId, bdi.patientName, bdi.mobile, bdi.gender, bdi.executorId, bdi.executorName, bdi.price, bdi.quantity, bdi.totalOriginalAmount, bdi.discountAmount, bdi.totalOriginalAmount - bdi.discountAmount AS actualAmount FROM ( SELECT bbd.org_id AS orgId, bp.billId, bbd.bill_detail_id AS billDetailId, bbd.item_id AS itemId, bti.item_num AS itemNum, bti.item_name AS itemName, bbd.item_type AS itemType, bti.category_id AS categoryId, bti.category_name AS categoryName, bp.billNum, bp.orderDate, bp.patientId, bp.patientName, bp.pinyinName, bp.mobile, bp.gender, bbd.executor_id AS executorId, be.employee_name AS executorName, bbd.price, bbd.quantity, bbd.price * bbd.quantity AS totalOriginalAmount, bbd.discount_amount AS discountAmount FROM base_bill_detail bbd LEFT JOIN base_tariff_info bti ON bbd.item_id = bti.item_id AND bbd.item_type = bti.item_type LEFT JOIN ( SELECT bb.bill_id AS billId, bb.order_date AS orderDate, bb.patient_id AS patientId, bb.bill_num AS billNum, bp.`name` AS patientName, bp.gender AS gender, bp.mobile AS mobile, bp.pinyin_name AS pinyinName FROM base_bill bb LEFT JOIN base_patient bp ON bb.patient_id = bp.patient_id ) bp ON bbd.bill_id = bp.billId LEFT JOIN base_employee be ON bbd.executor_id = be.user_id ) bdi
AND bdi.orgId = #{query.orgId}
AND DATE_FORMAT( bdi.orderDate, '%Y-%m' ) = #{query.orderDate}
AND concat(ifnull(bdi.patientName, ''), ifnull(bdi.pinyinName, ''), ifnull(bdi.mobile, '')) Like concat('%', #{query.keyWord}, '%')
ORDER BY bdi.orderDate DESC, bdi.billId, bdi.billDetailId

SELECT employeeId, employeeName, baseWorkload, bonusCoefficient, postNames, actualWorkload, supplementWorkload, receivedWorkload, refundWorkload, processingFee, largeMaterialCost FROM ( SELECT bup.org_id, bup.user_id AS employeeId, be.employee_name AS employeeName, IFNULL(be.work_amount, 0) AS baseWorkload, IFNULL(be.bonus_coefficient, 0) AS bonusCoefficient, GROUP_CONCAT( DISTINCT bup.post_name SEPARATOR ',' ) AS postNames, IFNULL( bbd.actualWorkload, 0 ) AS actualWorkload, IFNULL( bbd.supplementWorkload, 0 ) AS supplementWorkload, IFNULL( bbd1.receivedWorkload, 0 ) AS receivedWorkload, IFNULL( brd.refundWorkload, 0 ) AS refundWorkload, IFNULL( ewc.processingFee, 0 ) AS processingFee, IFNULL( ewc.largeMaterialCost, 0 ) AS largeMaterialCost FROM base_user_post bup LEFT JOIN base_employee be ON bup.user_id = be.user_id LEFT JOIN ( SELECT bbd.org_id, bbd.order_date, bbd.executor_id, SUM( bbd.coupon_workload ) AS supplementWorkload, SUM( bbd.price * bbd.quantity - bbd.discount_amount ) AS actualWorkload FROM ( SELECT bb.org_id, bb.order_date, bbd.executor_id, bbd.coupon_workload, bbd.discount_amount, bbd.price, bbd.quantity FROM base_bill_detail bbd LEFT JOIN base_bill bb ON bbd.bill_id = bb.bill_id ) bbd
and bbd.executor_id IS NOT NULL
and DATE_FORMAT( bbd.order_date, '%Y-%m' ) = #{query.queryDate}
and DATE_FORMAT( bbd.order_date, '%Y' ) = #{query.queryDate}
GROUP BY bbd.org_id, bbd.executor_id ) bbd ON bup.user_id = bbd.executor_id AND bup.org_id = bbd.org_id LEFT JOIN ( SELECT bbd.org_id, bbd.executor_id, SUM( bbd.received_amount ) AS receivedWorkload FROM ( SELECT bb.org_id, bb.bill_date, bbd.executor_id, bbd.received_amount FROM base_bill_detail bbd LEFT JOIN base_bill bb ON bbd.bill_id = bb.bill_id ) bbd
and bbd.executor_id IS NOT NULL
and DATE_FORMAT( bbd.bill_date, '%Y-%m' ) = #{query.queryDate}
and DATE_FORMAT( bbd.bill_date, '%Y' ) = #{query.queryDate}
GROUP BY bbd.org_id, bbd.executor_id ) bbd1 ON bup.user_id = bbd1.executor_id AND bup.org_id = bbd1.org_id LEFT JOIN ( SELECT brd.org_id, SUM( brd.refund_amount ) AS refundWorkload, brd.executor_id FROM ( SELECT br.org_id, br.refund_date, brd.refund_amount, bbd.executor_id FROM base_refund_detail brd LEFT JOIN base_bill_detail bbd ON brd.bill_detail_id = bbd.bill_detail_id LEFT JOIN base_refund br ON brd.refund_id = br.refund_id ) brd
and brd.executor_id IS NOT NULL
and DATE_FORMAT( brd.refund_date, '%Y-%m' ) = #{query.queryDate}
and DATE_FORMAT( brd.refund_date, '%Y' ) = #{query.queryDate}
GROUP BY brd.org_id, brd.executor_id ) brd ON bup.user_id = brd.executor_id AND bup.org_id = bup.org_id LEFT JOIN ( SELECT ewc.org_id, SUM( ewc.processing_fee ) AS processingFee, SUM( ewc.material_fee ) AS largeMaterialCost, ewc.user_id FROM employee_workload_cost ewc
and DATE_FORMAT( ewc.entry_month, '%Y-%m' ) = #{query.queryDate}
and DATE_FORMAT( ewc.entry_month, '%Y' ) = #{query.queryDate}
GROUP BY ewc.user_id, ewc.org_id ) ewc ON bup.user_id = ewc.user_id AND bup.org_id = ewc.org_id GROUP BY bup.user_id, bup.org_id ) bup
and bup.org_id = #{query.orgId}
and bup.employeeId in
#{item}

SELECT employeeId, employeeName, postNames, actualWorkload, supplementWorkload, receivedWorkload, refundWorkload, processingFee, largeMaterialCost FROM ( SELECT bup.org_id, bup.user_id AS employeeId, be.employee_name AS employeeName, GROUP_CONCAT( DISTINCT bup.post_name SEPARATOR ',' ) AS postNames, IFNULL( bbd.actualWorkload, 0 ) AS actualWorkload, ifnull( bbd.supplementWorkload, 0 ) AS supplementWorkload, ifnull( bbd1.receivedWorkload, 0 ) AS receivedWorkload, ifnull( brd.refundWorkload, 0 ) AS refundWorkload, ifnull( ewc.processingFee, 0 ) AS processingFee, ifnull( ewc.largeMaterialCost, 0 ) AS largeMaterialCost FROM base_user_post bup LEFT JOIN base_employee be ON bup.user_id = be.user_id LEFT JOIN ( SELECT bbd.org_id, bbd.order_date, bbd.executor_id, SUM( bbd.coupon_workload ) AS supplementWorkload, SUM( bbd.price * bbd.quantity - bbd.discount_amount ) AS actualWorkload FROM ( SELECT bb.org_id, bb.order_date, bbd.executor_id, bbd.coupon_workload, bbd.discount_amount, bbd.price, bbd.quantity FROM base_bill_detail bbd LEFT JOIN base_bill bb ON bbd.bill_id = bb.bill_id ) bbd
and bbd.executor_id IS NOT NULL
and DATE_FORMAT( bbd.order_date, '%Y-%m' ) = #{query.queryDate}
and DATE_FORMAT( bbd.order_date, '%Y' ) = #{query.queryDate}
GROUP BY bbd.org_id, bbd.executor_id ) bbd ON bup.user_id = bbd.executor_id AND bup.org_id = bbd.org_id LEFT JOIN ( SELECT bbd.org_id, bbd.executor_id, SUM( bbd.received_amount ) AS receivedWorkload FROM ( SELECT bb.org_id, bb.bill_date, bbd.executor_id, bbd.received_amount FROM base_bill_detail bbd LEFT JOIN base_bill bb ON bbd.bill_id = bb.bill_id ) bbd
and bbd.executor_id IS NOT NULL
and DATE_FORMAT( bbd.bill_date, '%Y-%m' ) = #{query.queryDate}
and DATE_FORMAT( bbd.bill_date, '%Y' ) = #{query.queryDate}
GROUP BY bbd.org_id, bbd.executor_id ) bbd1 ON bup.user_id = bbd1.executor_id AND bup.org_id = bbd1.org_id LEFT JOIN ( SELECT brd.org_id, SUM( brd.refund_amount ) AS refundWorkload, brd.executor_id FROM ( SELECT br.org_id, br.refund_date, brd.refund_amount, bbd.executor_id FROM base_refund_detail brd LEFT JOIN base_bill_detail bbd ON brd.bill_detail_id = bbd.bill_detail_id LEFT JOIN base_refund br ON brd.refund_id = br.refund_id ) brd
and brd.executor_id IS NOT NULL
and DATE_FORMAT( brd.refund_date, '%Y-%m' ) = #{query.queryDate}
and DATE_FORMAT( brd.refund_date, '%Y' ) = #{query.queryDate}
GROUP BY brd.org_id, brd.executor_id ) brd ON bup.user_id = brd.executor_id AND bup.org_id = bup.org_id LEFT JOIN ( SELECT ewc.org_id, SUM( ewc.processing_fee ) AS processingFee, SUM( ewc.material_fee ) AS largeMaterialCost, ewc.user_id FROM employee_workload_cost ewc
and DATE_FORMAT( ewc.entry_month, '%Y-%m' ) = #{query.queryDate}
and DATE_FORMAT( ewc.entry_month, '%Y' ) = #{query.queryDate}
GROUP BY ewc.user_id, ewc.org_id ) ewc ON bup.user_id = ewc.user_id AND bup.org_id = ewc.org_id GROUP BY bup.user_id, bup.org_id ) bup
and bup.org_id = #{query.orgId}
and bup.employeeId in
#{item}

select bdp.categoryId, bdp.categoryName, sum(bdp.totalOriginalAmount) - sum(bdp.discountAmount) as totalActualAmount, sum(bdp.discountAmount) as totalDiscountAmount from ( select bb.org_id as orgId, bti.item_type as itemType, bti.category_id as categoryId, bti.category_name as categoryName, bbd.discount_amount as discountAmount, bbd.price * bbd.quantity as totalOriginalAmount, date_format(bb.order_date, '%Y-%m') as orderDate from base_bill_detail bbd left join base_tariff_info bti on bbd.item_id = bti.item_id and bbd.item_type = bti.item_type left join base_bill bb on bbd.bill_id = bb.bill_id order by bti.item_type, bti.category_id) bdp
and bdp.orgId = #{query.orgId}
and bdp.orderDate = #{query.queryDate}
group by bdp.itemType, bdp.categoryId

SELECT orgId, billId, billNum, DATE_FORMAT(orderDate, '%Y-%m-%d') as orderDate, patientId, patientName, mobile, totalOriginalAmount, privilegeAmount, actualAmount, ewd.actualWorkload, executorId FROM ( SELECT ebd.orgId, ebd.billId, ebd.billNum, ebd.orderDate, ebd.patientId, ebd.patientName, ebd.pinyinName, ebd.mobile, SUM( ebd.originalAmount ) AS totalOriginalAmount, ebd.privilegeAmount, ebd.actualAmount, IFNULL( ew.actualWorkload, 0 ) as actualWorkload, ebd.executorId FROM ( SELECT bbp.org_id AS orgId, bbp.bill_id AS billId, bbp.bill_num AS billNum, bbp.order_date AS orderDate, bbp.patient_id AS patientId, bbp.`name` AS patientName, bbp.pinyin_name AS pinyinName, bbp.mobile, bbp.order_amount AS totalOriginalAmount, bbp.privilege_amount AS privilegeAmount, bbp.actual_amount AS actualAmount, bbd.price * bbd.quantity AS originalAmount, bbd.discount_amount AS discountAmount, bbd.executor_id AS executorId FROM base_bill_detail bbd LEFT JOIN ( SELECT bb.org_id, bb.bill_id, bb.bill_num, bb.order_date, bb.order_amount, bb.privilege_amount, bb.actual_amount, bb.patient_id, bp.`name`, bp.mobile, bp.pinyin_name FROM base_bill bb LEFT JOIN base_patient bp ON bb.patient_id = bp.patient_id ) bbp ON bbd.bill_id = bbp.bill_id ) ebd LEFT JOIN ( SELECT SUM( ew.originalAmount - ew.discountAmount ) AS actualWorkload, ew.billId, ew.executorId FROM ( SELECT bbd.bill_id AS billId, bbd.price * bbd.quantity AS originalAmount, bbd.discount_amount AS discountAmount, bbd.executor_id AS executorId FROM base_bill_detail bbd WHERE bbd.executor_id IS NOT NULL GROUP BY bbd.bill_detail_id ) ew GROUP BY ew.billId, ew.executorId ) ew ON ebd.executorId = ew.executorId AND ebd.billId = ew.billId
and ebd.orgId = #{query.orgId}
and DATE_FORMAT( ebd.orderDate, '%Y-%m' ) = #{query.queryDate}
and DATE_FORMAT( ebd.orderDate, '%Y' ) = #{query.queryDate}
and ebd.executorId = #{query.employeeId}
GROUP BY ebd.billId ) ewd
and concat(IFNULL(ewd.patientName, ''), IFNULL(ewd.pinyinName, ''), IFNULL(ewd.mobile, '')) Like concat('%', #{query.keyword}, '%')
and ewd.billNum like concat('%', #{query.billNum} ,'%')
and DATE_FORMAT(ewd.orderDate, '%Y-%m-%d') = #{query.orderDate}
ORDER BY ewd.orderDate DESC

select bbd.bill_detail_id as orderDetailId, bbd.item_type as itemType, bbd.item_id as itemId, bti.item_num as itemNum, bti.item_name as itemName, bbd.price * bbd.quantity as originalPrice, bbd.discount_amount as discountAmount, bbd.price * bbd.quantity - bbd.discount_amount as actualWorkload from base_bill_detail bbd left join base_tariff_info bti on bbd.item_type = bti.item_type and bbd.item_id = bti.item_id
and bbd.bill_id = #{query.billId}
and bbd.executor_id = #{query.employeeId}

SELECT orgId, billId, billNum, DATE_FORMAT(orderDate, '%Y-%m-%d %H:%i') as orderDate, DATE_FORMAT(billDate, '%Y-%m-%d %H:%i') as chargeDate, patientId, patientName, mobile, ewd.receivedWorkload FROM ( SELECT ebd.orgId, ebd.billId, ebd.billNum, ebd.orderDate, ebd.billDate, ebd.patientId, ebd.patientName, ebd.pinyinName, ebd.mobile, IFNULL( ew.receivedWorkload, 0 ) AS receivedWorkload, ebd.executorId FROM ( SELECT bbp.org_id AS orgId, bbp.bill_id AS billId, bbp.bill_num AS billNum, bbp.order_date AS orderDate, bbp.bill_date AS billDate, bbp.patient_id AS patientId, bbp.`name` AS patientName, bbp.pinyin_name AS pinyinName, bbp.mobile, bbd.executor_id AS executorId FROM base_bill_detail bbd LEFT JOIN ( SELECT bb.org_id, bb.bill_id, bb.bill_num, bb.order_date, bb.bill_date, bb.patient_id, bp.`name`, bp.mobile, bp.pinyin_name FROM base_bill bb LEFT JOIN base_patient bp ON bb.patient_id = bp.patient_id ) bbp ON bbd.bill_id = bbp.bill_id ) ebd LEFT JOIN ( SELECT SUM( ew.receivedAmount ) AS receivedWorkload, ew.billId, ew.executorId FROM ( SELECT bbd.bill_id AS billId, bbd.received_amount AS receivedAmount, bbd.executor_id AS executorId FROM base_bill_detail bbd WHERE bbd.executor_id IS NOT NULL GROUP BY bbd.bill_detail_id ) ew GROUP BY ew.billId, ew.executorId ) ew ON ebd.executorId = ew.executorId AND ebd.billId = ew.billId
and ebd.orgId = #{query.orgId}
and DATE_FORMAT( ebd.orderDate, '%Y-%m' ) = #{query.queryDate}
and DATE_FORMAT( ebd.orderDate, '%Y' ) = #{query.queryDate}
and ebd.executorId = #{query.employeeId}
GROUP BY ebd.billId ) ewd
and concat(IFNULL(ewd.patientName, ''), IFNULL(ewd.pinyinName, ''), IFNULL(ewd.mobile, '')) Like concat('%', #{query.keyword}, '%')
and ewd.billNum like concat('%', #{query.billNum} ,'%')
and DATE_FORMAT(ewd.orderDate, '%Y-%m-%d') = #{query.orderDate}
ORDER BY ewd.orderDate DESC

SELECT bbd.bill_detail_id AS orderDetailId, bbd.item_type AS itemType, bbd.item_id AS itemId, bti.item_num AS itemNum, bti.item_name AS itemName, bbd.received_amount as receivedWorkload FROM base_bill_detail bbd LEFT JOIN base_tariff_info bti ON bbd.item_type = bti.item_type AND bbd.item_id = bti.item_id
and bbd.bill_id = #{query.billId}
and bbd.executor_id = #{query.employeeId}

SELECT orgId, billId, billNum, DATE_FORMAT( orderDate, '%Y-%m-%d' ), patientId, patientName, mobile, totalOriginalAmount, privilegeAmount, actualAmount, supplyWorkload FROM ( SELECT ebd.orgId, ebd.billId, ebd.billNum, ebd.orderDate, ebd.patientId, ebd.patientName, ebd.pinyinName, ebd.mobile, SUM( ebd.originalAmount ) AS totalOriginalAmount, ebd.privilegeAmount, ebd.actualAmount, IFNULL( ew.couponWorkload, 0 ) AS supplyWorkload, ebd.executorId FROM ( SELECT bbp.org_id AS orgId, bbp.bill_id AS billId, bbp.bill_num AS billNum, bbp.order_date AS orderDate, bbp.patient_id AS patientId, bbp.`name` AS patientName, bbp.pinyin_name AS pinyinName, bbp.mobile, bbp.order_amount AS totalOriginalAmount, bbp.privilege_amount AS privilegeAmount, bbp.actual_amount AS actualAmount, bbd.price * bbd.quantity AS originalAmount, bbd.discount_amount AS discountAmount, bbd.executor_id AS executorId FROM base_bill_detail bbd LEFT JOIN ( SELECT bb.org_id, bb.bill_id, bb.bill_num, bb.order_date, bb.order_amount, bb.privilege_amount, bb.actual_amount, bb.patient_id, bp.`name`, bp.mobile, bp.pinyin_name FROM base_bill bb LEFT JOIN base_patient bp ON bb.patient_id = bp.patient_id ) bbp ON bbd.bill_id = bbp.bill_id ) ebd LEFT JOIN ( SELECT SUM( ew.couponWorkload ) AS couponWorkload, ew.billId, ew.executorId FROM ( SELECT bbd.bill_id AS billId, bbd.coupon_workload AS couponWorkload, bbd.executor_id AS executorId FROM base_bill_detail bbd WHERE bbd.executor_id IS NOT NULL GROUP BY bbd.bill_detail_id ) ew GROUP BY ew.billId, ew.executorId ) ew ON ebd.executorId = ew.executorId AND ebd.billId = ew.billId
and ebd.orgId = #{query.orgId}
and DATE_FORMAT( ebd.orderDate, '%Y-%m' ) = #{query.queryDate}
and DATE_FORMAT( ebd.orderDate, '%Y' ) = #{query.queryDate}
and ebd.executorId = #{query.employeeId}
GROUP BY ebd.billId ) ewd
and concat(IFNULL(ewd.patientName, ''), IFNULL(ewd.pinyinName, ''), IFNULL(ewd.mobile, '')) Like concat('%', #{query.keyword}, '%')
and ewd.billNum like concat('%', #{query.billNum} ,'%')
and DATE_FORMAT(ewd.orderDate, '%Y-%m-%d') = #{query.orderDate}
ORDER BY ewd.orderDate DESC

SELECT bbd.bill_detail_id AS orderDetailId, bbd.item_type AS itemType, bbd.item_id AS itemId, bti.item_num AS itemNum, bti.item_name AS itemName, bbd.coupon_workload as supplyWorkload FROM base_bill_detail bbd LEFT JOIN base_tariff_info bti ON bbd.item_id = bti.item_id LEFT JOIN base_benefit bb on (bb.order_id=bbd.bill_id and bb.item_id=bti.item_id)
bbd.item_type=0 and bb.coupon_type in (0,1,2,3)
and bbd.bill_id = #{query.billId}
and bbd.executor_id = #{query.employeeId}

SELECT awd.bill_id as billId, awd.bill_num as billNum, DATE_FORMAT(awd.order_date, '%Y-%m-%d') as orderDate, awd.patient_id as patientId, awd.`name` as patientName, awd.mobile, awd.registered_dentist_id as matchingDentistId, awd.employee_name as matchingDentistName, SUM(ifnull(awd.actualAmount, 0)) as actualWorkload FROM ( SELECT btp.bill_id, btp.bill_num, btp.order_date, btp.patient_id, btp.`name`, btp.pinyin_name, btp.mobile, btp.treatment_id, btp.registered_dentist_id, btp.employee_name, btp.originalAmount - btp.discount_amount AS actualAmount FROM ( SELECT bbp.org_id, bbd.bill_id, bbd.price * bbd.quantity AS originalAmount, bbd.discount_amount, bbp.bill_num, bbp.order_date, bbp.patient_id, bbp.`name`, bbp.pinyin_name, bbp.mobile, bbp.treatment_id, bbp.treat_start_time, bbp.registered_dentist_id, bbp.employee_name, bbp.assistant_1, bbp.assistant_2, bbp.assistant_3 FROM base_bill_detail bbd LEFT JOIN ( SELECT bb.org_id, btp.treatment_id, bb.bill_id, bb.bill_num, bb.order_date, bb.patient_id, bp.`name`, bp.mobile, bp.pinyin_name, btp.treat_start_time, btp.registered_dentist_id, btp.employee_name, btp.assistant_1, btp.assistant_2, btp.assistant_3 FROM base_bill bb LEFT JOIN base_patient bp ON bb.patient_id = bp.patient_id LEFT JOIN ( SELECT btp.treatment_id, btp.treat_start_time, btp.registered_dentist_id, be.employee_name, btp.assistant_1, btp.assistant_2, btp.assistant_3 FROM base_treatment_process btp LEFT JOIN base_employee be ON btp.registered_dentist_id = be.user_id GROUP BY btp.treatment_id ) btp ON bb.treatment_id = btp.treatment_id where bb.bill_num is not null ) bbp ON bbd.bill_id = bbp.bill_id WHERE bbd.executor_id IS NOT NULL ) btp
AND btp.org_id = #{query.orgId}
AND DATE_FORMAT( btp.treat_start_time, '%Y-%m-%d' ) >= #{query.startDate}
AND DATE_FORMAT( btp.treat_start_time, '%Y-%m-%d' ) <= #{query.endDate}
AND DATE_FORMAT( btp.treat_start_time, '%Y-%m' ) >= #{query.startDate}
AND DATE_FORMAT( btp.treat_start_time, '%Y-%m' ) <= #{query.endDate}
AND DATE_FORMAT( btp.treat_start_time, '%Y' ) >= #{query.startDate}
AND DATE_FORMAT( btp.treat_start_time, '%Y' ) <= #{query.endDate}
AND btp.assistant_1 = #{query.assistantId}
AND btp.assistant_2 = #{query.assistantId}
AND btp.assistant_3 = #{query.assistantId}
) awd
and concat(IFNULL(awd.`name`, ''), IFNULL(awd.pinyin_name, ''), IFNULL(awd.mobile, '')) like concat('%', #{query.keyword}, '%')
and concat(awd.bill_num) like concat('%', #{query.billNum}, '%')
and DATE_FORMAT(awd.order_date, '%Y-%m-%d') >= #{query.orderStartDate}
and DATE_FORMAT(awd.order_date, '%Y-%m-%d') <= #{query.orderEndDate}
GROUP BY awd.treatment_id

SELECT * FROM ( SELECT bbd.itemId, bbd.itemType, bbd.itemNum, bbd.itemName, bbd.categoryId, bbd.categoryName, SUM( bbd.quantity ) as totalBillCount FROM ( SELECT bbd.item_id AS itemId, bbd.item_type AS itemType, bbd.source_type, bti.item_num AS itemNum, bti.item_name AS itemName, bti.category_id AS categoryId, bti.category_name AS categoryName, bbd.quantity, bb.org_id, bb.bill_date, bb.bill_num FROM base_bill_detail bbd LEFT JOIN base_bill bb ON bbd.bill_id = bb.bill_id LEFT JOIN base_tariff_info bti ON bbd.item_id = bti.item_id AND bbd.item_type = bti.item_type ) bbd
and bbd.bill_date IS NOT NULL and bbd.source_type = 0
and bbd.org_id = #{query.orgId}
and DATE_FORMAT(bbd.bill_date, '%Y-%m-%d') >= #{query.startDate}
and DATE_FORMAT(bbd.bill_date, '%Y-%m-%d') <= #{query.endDate}
and DATE_FORMAT(bbd.bill_date, '%Y-%m') >= #{query.startDate}
and DATE_FORMAT(bbd.bill_date, '%Y-%m') <= #{query.endDate}
and DATE_FORMAT(bbd.bill_date, '%Y') >= #{query.startDate}
and DATE_FORMAT(bbd.bill_date, '%Y') <= #{query.endDate}
GROUP BY bbd.itemId, bbd.itemType ORDER BY bbd.itemType, bbd.itemId ) bbd
and bbd.categoryId in
#{item}

SELECT bbd.billDetailId, DATE_FORMAT(bbd.orderDate, '%Y-%m-%d'), DATE_FORMAT(bbd.billDate, '%Y-%m-%d'), bbd.billNum, bbd.quantity, bbd.patientId, bbd.patientName, bbd.mobile, bbd.regDentistId, bbd.regDentistName FROM ( SELECT bbd.billDetailId, bbd.billDate, bbd.orderDate, bbd.billNum, bbd.quantity, bbd.patientId, bbd.patientName, bbd.pinyinName, bbd.mobile, bbd.regDentistId, bbd.regDentistName FROM ( SELECT bbd.orgId, bbd.billDetailId, bbd.billDate, bbd.orderDate, bbd.billNum, bbd.itemId, bbd.itemType, bbd.quantity, bbd.patientId, bp.`name` AS patientName, bp.pinyin_name AS pinyinName, bp.mobile, btp.user_id AS regDentistId, btp.employee_name AS regDentistName FROM ( SELECT bbd.bill_detail_id AS billDetailId, bbd.item_id AS itemId, bbd.item_type AS itemType, bbd.quantity, bb.org_id AS orgId, bb.order_date AS orderDate, bb.bill_date AS billDate, bb.bill_num AS billNum, bb.patient_id AS patientId, bb.treatment_id FROM base_bill_detail bbd LEFT JOIN base_bill bb ON bbd.bill_id = bb.bill_id WHERE bbd.source_type = 0 ) bbd LEFT JOIN base_patient bp ON bbd.patientId = bp.patient_id LEFT JOIN ( SELECT btp.treatment_id, be.user_id, be.employee_name FROM base_treatment_process btp LEFT JOIN base_employee be ON btp.registered_dentist_id = be.user_id GROUP BY btp.treatment_id ) btp ON bbd.treatment_id = btp.treatment_id ) bbd
AND bbd.billDate IS NOT NULL
and bbd.orgId = #{query.orgId}
and bbd.itemId = #{query.itemId}
and bbd.itemType = #{query.itemType}
and DATE_FORMAT(bbd.billDate, '%Y-%m-%d') >= #{query.startDate}
and DATE_FORMAT(bbd.billDate, '%Y-%m-%d') <= #{query.endDate}
and DATE_FORMAT(bbd.billDate, '%Y-%m') >= #{query.startDate}
and DATE_FORMAT(bbd.billDate, '%Y-%m') <= #{query.endDate}
and DATE_FORMAT(bbd.billDate, '%Y') >= #{query.startDate}
and DATE_FORMAT(bbd.billDate, '%Y') <= #{query.endDate}
) bbd
and concat(IFNULL(bbd.patientName, ''), IFNULL(bbd.pinyinName, ''), IFNULL(bbd.mobile, '')) like concat('%', #{query.keyword}, '%')
and bbd.billNum like concat('%', #{query.billNum}, '%')
and DATE_FORMAT(bbd.billDate, '%Y-%m-%d') >= #{query.billStartDate}
and DATE_FORMAT(bbd.billDate, '%Y-%m-%d') <= #{query.billEndDate}
and bbd.regDentistId in
#{item}

SELECT IFNULL(SUM( bbd.totalClinicActualReceiveWorkload ), 0) AS totalClinicActualReceiveWorkload, IFNULL(SUM( bbd.totalClinicReceivedWorkload ), 0) AS totalClinicReceivedWorkload, IFNULL(SUM( bbd.totalClinicReceivedNotWorkload ), 0) AS totalClinicReceivedNotWorkload FROM ( SELECT bo.org_id, IFNULL( bbd.totalClinicActualReceiveWorkload, 0 ) AS totalClinicActualReceiveWorkload, IFNULL( bbd.totalClinicReceivedWorkload, 0 ) AS totalClinicReceivedWorkload, IFNULL( bbd1.totalClinicReceivedNotWorkload, 0 ) AS totalClinicReceivedNotWorkload FROM base_organization bo LEFT JOIN ( SELECT bbd.org_id, SUM( bbd.totalAmount - bbd.discount_amount ) AS totalClinicActualReceiveWorkload, SUM( bbd.received_amount ) AS totalClinicReceivedWorkload FROM ( SELECT bb.org_id, bb.bill_date, bbd.received_amount, bbd.price * bbd.quantity AS totalAmount, bbd.discount_amount FROM base_bill_detail bbd LEFT JOIN base_bill bb ON bbd.bill_id = bb.bill_id WHERE bbd.executor_id IS NOT NULL ) bbd
and DATE_FORMAT( bbd.bill_date, '%Y-%m-%d') >= #{query.startDate}
and DATE_FORMAT( bbd.bill_date, '%Y-%m-%d') <= #{query.endDate}
and DATE_FORMAT( bbd.bill_date, '%Y-%m') >= #{query.startDate}
and DATE_FORMAT( bbd.bill_date, '%Y-%m') <= #{query.endDate}
and DATE_FORMAT( bbd.bill_date, '%Y') >= #{query.startDate}
and DATE_FORMAT( bbd.bill_date, '%Y') <= #{query.endDate}
GROUP BY bbd.org_id ) bbd ON bo.org_id = bbd.org_id LEFT JOIN ( SELECT bbd.org_id, SUM( bbd.received_amount ) AS totalClinicReceivedNotWorkload FROM ( SELECT bb.org_id, bb.bill_date, bbd.received_amount FROM base_bill_detail bbd LEFT JOIN base_bill bb ON bbd.bill_id = bb.bill_id WHERE bbd.executor_id IS NULL ) bbd
and DATE_FORMAT( bbd.bill_date, '%Y-%m-%d') >= #{query.startDate}
and DATE_FORMAT( bbd.bill_date, '%Y-%m-%d') <= #{query.endDate}
and DATE_FORMAT( bbd.bill_date, '%Y-%m') >= #{query.startDate}
and DATE_FORMAT( bbd.bill_date, '%Y-%m') <= #{query.endDate}
and DATE_FORMAT( bbd.bill_date, '%Y') >= #{query.startDate}
and DATE_FORMAT( bbd.bill_date, '%Y') <= #{query.endDate}
GROUP BY bbd.org_id ) bbd1 ON bo.org_id = bbd1.org_id GROUP BY bo.org_id ) bbd
and bbd.org_id in
#{item}

SELECT bbd.bill_detail_id AS billDetailId, bbd.billDate, bbd.bill_num AS billNum, bbd.patient_id AS patientId, bp.medical_number AS medicalNum, bp.mobile AS patientMobile, bp.`name` AS patientName, bbd.item_id AS itemId, bbd.item_type AS itemType, bti.category_id AS itemCategoryId, bti.category_name AS itemCategoryName, bti.item_name AS itemName, bbd.quantity AS quantity, ( bbd.originalAmount - bbd.discount_amount ) AS itemActualAmount, bbd.actual_amount AS billActualAmount, bbd.coupon_workload AS itemSupplyWorkloadAmount FROM ( SELECT bbd.org_id, bbd.bill_detail_id, bbd.item_id, bbd.item_type, bbd.quantity * bbd.price AS originalAmount, bbd.quantity, bbd.discount_amount, bbd.coupon_workload, bb.patient_id, bb.actual_amount, DATE_FORMAT(bb.bill_date, '%Y-%m') as billDate, bb.bill_num FROM base_bill_detail bbd LEFT JOIN base_bill bb ON bbd.bill_id = bb.bill_id ) bbd LEFT JOIN base_patient bp ON bbd.patient_id = bp.patient_id LEFT JOIN base_tariff_info bti ON bbd.item_type = bti.item_type AND bbd.item_id = bti.item_id
AND bbd.bill_num IS NOT NULL AND bbd.billDate IS NOT NULL
AND bbd.org_id = #{query.orgId}
AND bbd.billDate = #{query.currentMonth}
GROUP BY bbd.bill_detail_id

SELECT bbp.bill_pay_id AS billPayId, DATE_FORMAT( bbp.payee_date, '%Y-%m-%d' ) AS payeeDate, DATE_FORMAT( bb.bill_date, '%Y-%m-%d' ) AS billDate, bb.bill_num AS billNum, bb.patient_id AS patientId, bb.`name` AS patientName, bb.mobile AS patientMobile, btp.regDentistId, btp.regDentistName AS regDentistName, bb.order_amount AS orderAmount, bb.privilege_amount AS privilegeAmount, bb.actual_amount AS actualAmount, bbp.received_amount AS receivedAmount, bbp.still_owe_amount AS stillOweAmount, bb.debt_amount AS billDebtAmount, bbp.payee_user_id AS payeeId, be.employee_name AS payeeName FROM base_bill_pay bbp LEFT JOIN base_employee be ON bbp.payee_user_id = be.user_id LEFT JOIN ( SELECT btp.treatment_id, btp.registered_dentist_id AS regDentistId, be.employee_name AS regDentistName FROM base_treatment_process btp LEFT JOIN base_employee be ON btp.registered_dentist_id = be.user_id GROUP BY btp.treatment_id, btp.registered_dentist_id, be.employee_name ) btp ON bbp.treatment_id = btp.treatment_id LEFT JOIN ( SELECT bb.org_id, bb.bill_id, bb.bill_num, bb.bill_date, bb.patient_id, bb.debt_amount, bp.`name`, bp.mobile, bb.order_amount, bb.privilege_amount, bb.actual_amount FROM base_bill bb LEFT JOIN base_patient bp ON bb.patient_id = bp.patient_id
and bb.org_id = #{query.orgId}
and DATE_FORMAT(bb.bill_date, '%Y-%m') = #{query.currentMonth}
) bb ON bbp.bill_id = bb.bill_id AND bbp.org_id = bb.org_id
and bbp.org_id = #{query.orgId}
and DATE_FORMAT(bbp.payee_date, '%Y-%m') = #{query.currentMonth}
